const express = require("express");

const app = express();
app.use(express.json());

const clubs = [
  { id: 1, name: "Robotics Club", focus: "engineering" },
];

app.post("/api/clubs", (req, res) => {
  const { name, focus } = req.body;

  if (!name || !focus) {
    return res.status(400).json({ error: "name and focus are required" });
  }

  const club = {
    id: clubs.length + 1,
    name,
    focus,
  };

  clubs.push(club);
  return res.status(201).json(club);
});

app.listen(3000, "127.0.0.1", () => {
  console.log("API listening on http://127.0.0.1:3000");
});
